  const solve = (V0, m) =&gt; {
    const k = E =&gt; Math.sqrt(2*m*me0*E*q)/hbar, K = E =&gt; Math.sqrt(2*m*me0*(V0 - E)*q)/hbar;
    const fs = [E =&gt; k(E)*Math.sin(k(E)*d/2) - K(E)*Math.cos(k(E)*d/2), E =&gt; k(E)*Math.cos(k(E)*d/2) + K(E)*Math.sin(k(E)*d/2)];
    const lv = [];
    for (const f of fs) { const N = 4000; let Ep = V0*1e-7, fp = f(Ep);
      for (let i = 1; i &lt;= N; i++) { const E = V0*(1e-7 + (1 - 2e-7)*i/N), fe = f(E);
        if (fp*fe &lt; 0) { let a = Ep, b = E; for (let j = 0; j &lt; 60; j++) { const c = (a + b)/2; if (f(a)*f(c) &lt;= 0) b = c; else a = c; } lv.push((a + b)/2); }
        Ep = E; fp = fe; } }
    return lv.sort((a, b) =&gt; a - b);
  };
  const el = solve(qw.dEc, qw.me), hh = solve(qw.dEv, qw.mh);
  const inf = (n, m) =&gt; (h*n)**2/(8*m*me0*d*d)/q;
  const Efin = qw.Eg + el[0] + hh[0], Einf = qw.Eg + inf(1, qw.me) + inf(1, qw.mh);
  return {el, hh, Efin, Einf, lamFin: 1239.84/Efin, lamInf: 1239.84/Einf, lamBulk: 1239.84/qw.Eg, inf1: inf(1, qw.me), inf2: inf(2, qw.me), infh: inf(1, qw.mh)};
}
