qwScan = {
  const hbar = 1.054571817e-34, me0 = 9.1093837e-31, q = 1.602176634e-19, h = 6.62607015e-34;
  const first = (V0, m, d) =&gt; { const k = E =&gt; Math.sqrt(2*m*me0*E*q)/hbar, K = E =&gt; Math.sqrt(2*m*me0*(V0 - E)*q)/hbar;
    const f = E =&gt; k(E)*Math.sin(k(E)*d/2) - K(E)*Math.cos(k(E)*d/2); let a = V0*1e-7, b = V0*(1 - 1e-7);
    // the ground state is the first root of the even equation; bracket it by scanning
    let Ep = a, fp = f(a); for (let i = 1; i &lt;= 2000; i++) { const E = a + (b - a)*i/2000, fe = f(E); if (fp*fe &lt; 0) { b = E; a = Ep; break; } Ep = E; fp = fe; }
    for (let j = 0; j &lt; 60; j++) { const c = (a + b)/2; if (f(a)*f(c) &lt;= 0) b = c; else a = c; } return (a + b)/2; };
  const out = [];
  for (let w = 2; w &lt;= 30; w += 0.5) {
    const d = w*1e-9, Ef = qw.Eg + first(qw.dEc, qw.me, d) + first(qw.dEv, qw.mh, d);
    const Ei = qw.Eg + (h**2/(8*qw.me*me0*d*d) + h**2/(8*qw.mh*me0*d*d))/q;
    out.push({w, lam: 1239.84/Ef, who: "finite well"}, {w, lam: 1239.84/Ei, who: "infinite well"});
  }
  return out;
}
